module Top;
    byte up [0:3] = '{8'h11, 8'h22, 8'h33, 8'h44};
    byte down [3:0] = '{8'h11, 8'h22, 8'h33, 8'h44};
    bit [31:0] v;
    initial begin
        v = {>>{up with [1 +: 2]}};
        $display("up[1+:2]=%h", v);
        v = {>>{down with [4]}};
        $display("down[4]=%h", v);
        v = {>>{down with [4:2]}};
        $display("down[4:2]=%h", v);
    end
endmodule
